                ->failWhenUsedSpaceIsAbovePercentage(
                    (int) config('health.flexpick.disk_fail_percent')
                ),

            OldestPendingAuditCheck::new(),
            AuditPipelineFailureRateCheck::new(),
            MailFailureRateCheck::new(),
            ScannerDegradationCheck::new(),
        ]);
    }
